from PIL import Image
import numpy as np
for cam in ['top','front','side','oblique']:
 im=np.array(Image.open('/app/output/'+cam+'.png')).astype(int)
 # saturated blue pixels in object/table area
 m=(im[:,:,2]>im[:,:,0]*1.2)&(im[:,:,2]>im[:,:,1]*1.08)&(im[:,:,2]>80)
 if cam=='top': m &= (np.indices(m.shape)[1]>100)&(np.indices(m.shape)[1]<215)&(np.indices(m.shape)[0]>55)&(np.indices(m.shape)[0]<145)
 elif cam=='front':m &= (np.indices(m.shape)[1]>90)&(np.indices(m.shape)[1]<200)&(np.indices(m.shape)[0]>60)&(np.indices(m.shape)[0]<150)
 elif cam=='side':m &= (np.indices(m.shape)[1]>70)&(np.indices(m.shape)[1]<190)&(np.indices(m.shape)[0]>45)&(np.indices(m.shape)[0]<140)
 else:m &= (np.indices(m.shape)[1]>100)&(np.indices(m.shape)[1]<230)&(np.indices(m.shape)[0]>50)&(np.indices(m.shape)[0]<170)
 y,x=np.where(m)
 print(cam,len(x), 'bbox', (x.min(),y.min(),x.max(),y.max()) if len(x) else None)
 if len(x):
  print('sample',[(int(x[i]),int(y[i]),im[y[i],x[i]].tolist()) for i in np.linspace(0,len(x)-1,min(10,len(x)),dtype=int)])
